fn choose_num(x: i8, y: i8) -> i8 {
    if x > y {
        return -1;
    }

    // Find the largest even integer in [x, y]
    // Start from y and go down to x, checking for even numbers.
    for num in (x..=y).rev() {
        if num % 2 == 0 {
            return num;
        }
    }

    // No even number found
    -1
}